export const getFrameFilename = (zeroBasedIndex: number): string => {
  const clamped = Math.max(0, Math.min(FRAME_COUNT - 1, Math.floor(zeroBasedIndex)));
  return FRAME_FILENAMES[clamped];
};

export const getIntroFramePath = (zeroBasedIndex: number): string =>
  `/intro/${getFrameFilename(zeroBasedIndex)}`;

export const getAiFramePath = (zeroBasedIndex: number): string =>
  `/Ai/${getFrameFilename(zeroBasedIndex)}`;

export const getSecurityFramePath = (zeroBasedIndex: number): string =>
  `/Security/${getFrameFilename(zeroBasedIndex)}`;

export const getCloudFramePath = (zeroBasedIndex: number): string =>
  `/Cloud/${getFrameFilename(zeroBasedIndex)}`;
